const PREF_BY = n => PREF.find(p => p[0]===n || p[0].replace(/[都道府県]$/,'')===String(n).replace(/[都道府県]$/,''));
const PREF_OF_CAP = n => PREF.find(p => p[1]===n);
const PREF_OF_THING = n => PREF.find(p => (p[5]||[]).includes(n));
