    if(u==='w_cont'){ out.tip = '6大陸：ユーラシア・アフリカ・北アメリカ・南アメリカ・オーストラリア・南極　3大洋：太平洋・大西洋・インド洋'; if(p.disp) out.figs.push(`<div class="dp56">${p.disp}</div>`); out.steps.push(`こたえ <b class="okc">${X(ans)}</b>${v ? `（${X(v)} では ないよ）` : ''}`); }
