    out.figs.push(`<div class="jo56">${Object.entries(JOSHI).slice(0,8).map(([k,d]) => `<span class="${k===ans?'ok':k===v?'ng':''}"><b>${k}</b><small>${X(d)}</small></span>`).join('')}</div>`);
