const today = () => (typeof dayKey === 'function' ? dayKey() : new Date().toISOString().slice(0, 10));
const dayNo = () => Math.floor((Date.now() - new Date().getTimezoneOffset() * 6e4) / 864e5);
const snd = t => { try{ sound(t); }catch(e){} };
