const RBC = {'人':'にん','回':'かい','枚':'まい','問':'もん','秒':'びょう','度':'ど','万':'まん','日':'にち','時':'じ','年':'ねん'};
const KJ = /[\u4E00-\u9FFF々〆]/, KANA = /[\u3040-\u30FFー]/;
function rbEsc(t){ return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function rbMake(key, rd, mode){
  let base = key, r = rd, tail = '';
  while(base.length > 1 && KANA.test(base[base.length - 1]) && r.length > 1 && r[r.length - 1] === base[base.length - 1]){ tail = base[base.length - 1] + tail; base = base.slice(0, -1); r = r.slice(0, -1); }
  if(mode === 'none' || (mode === 'hard' && !hardW(base))) return rbEsc(key);
  return `<ruby>${rbEsc(base)}<rt>${rbEsc(r)}</rt></ruby>${rbEsc(tail)}`;
}
function rbText(text, modeIn){
  const mode = modeIn || AS().settings.ruby; text = String(text ?? '');
  return text.split(/(\{[^|{}]+\|[^{}]+\})/).map(seg => {
    const m = seg.match(/^\{([^|{}]+)\|([^{}]+)\}$/); if(m) return rbMake(m[1], m[2], mode);
    if(mode === 'none') return rbEsc(seg);
    let out = '', i = 0;
    while(i < seg.length){
      if(!KJ.test(seg[i])){ out += rbEsc(seg[i]); i++; continue; }
      if(i > 0 && /[0-9０-９]/.test(seg[i - 1])){
        const c = seg[i];
        if(c === '分'){ const rd = '134680'.includes(seg[i - 1]) ? 'ぷん' : 'ふん'; if(seg[i + 1] === '間'){ out += rbMake('分間', rd + 'かん', mode); i += 2; } else { out += rbMake('分', rd, mode); i++; } continue; }
        if(RBC[c]){ out += rbMake(c, RBC[c], mode); i++; continue; }
      }
      let hit = null;
      for(let L = Math.min(RBK_MAX, seg.length - i); L >= 1; L--){ const k = seg.substr(i, L); if(RBD[k] !== undefined){ hit = k; break; } }
      if(hit){ out += rbMake(hit, RBD[hit], mode); i += hit.length; } else { out += rbEsc(seg[i]); i++; }
    }
    return out;
  }).join('');
}
const R = t => rbText(t);
const plainOf = t => String(t ?? '').replace(/\{([^|{}]+)\|[^{}]+\}/g, '$1');
function rubifyDOM(root){
  if(!root) return; const mode = AS().settings.ruby; if(mode === 'none') return;
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {acceptNode: n => (KJ.test(n.nodeValue) && n.parentElement && !n.parentElement.closest('ruby,rt,script,style,textarea,canvas,svg,[data-norb]')) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT});
  const L = []; while(w.nextNode()) L.push(w.currentNode);
  L.forEach(n => { const h = rbText(n.nodeValue, mode); if(h.indexOf('<ruby>') < 0) return; const t = document.createElement('template'); t.innerHTML = h; n.replaceWith(t.content); });
}
function hardW(k){ try{ const w = window.__yu659; return w && w.hardWord ? w.hardWord(k) : true; }catch(e){ return true; } }

