function AS(){
  const t = save.town || (save.town = {}); let fresh = false;
  if(!t.airport){ t.airport = {}; fresh = true; }
  const a = t.airport;
  if(fresh) a.tix = CFG.firstTix;
  a.tix = a.tix || 0; a.miles = a.miles || 0; a.stamps = a.stamps || {}; a.visits = a.visits || {}; a.sv = a.sv || {}; a.bag = a.bag || {};
  a.seen = a.seen || {}; a.miss = a.miss || {}; a.right = a.right || 0; a.trips = a.trips || 0; a.settings = a.settings || {ruby:'all'};
  if(a.settings.rv !== 2){ a.settings.rv = 2; a.settings.ruby = 'all'; }
  a.rankShown = a.rankShown || rankNo(a.miles); a.homeGot = a.homeGot || {}; a.friends = a.friends || {}; a.my = a.my || {a:0, b:0, g:0};
  try{ Object.keys(a.sv).forEach(k => { if(String(k).startsWith('fr_')) ensureFrFur(k); }); }catch(e){}
  if(!a.daily || a.daily.d !== today()) a.daily = {d:today(), earn:0, sky:0, tower:0};
  return a;
}
function ensureFrFur(k){
  if(FUR('ap_' + k)) return; const it = ITEM(String(k).slice(3)); if(!it) return;
  const src = it.img || art(it.art); try{ DEFAULT_ART['ap_' + k] = src; }catch(e){}
  FURNITURE.push({id:'ap_' + k, name:'ミニ' + it.name, art:'ap_' + k, type:'fur', price:0, lv:1, sty:3, special:true, ev:'airport'});
}
