/* ---------- 全面ステージ（イラストを画面いっぱいに） ---------- */
function fitAllStages(){
  if(!ROOT) return;
  ROOT.querySelectorAll('.apstage').forEach(st => {
    const iw = +st.dataset.iw, ih = +st.dataset.ih, mode = st.dataset.mode || 'cover', fx = +(st.dataset.fx || .5), fy = +(st.dataset.fy || .5), box = st.parentElement;
    const W = box.clientWidth, H = box.clientHeight; if(!W || !H) return;
    const s = mode === 'contain' ? Math.min(W / iw, H / ih) : Math.max(W / iw, H / ih), w = iw * s, h = ih * s;
    st.style.width = w + 'px'; st.style.height = h + 'px';
    if(box.classList.contains('appan')) return;
    const al = (len, b, f) => len <= b ? (b - len) / 2 : Math.max(b - len, Math.min(0, b / 2 - f * len));
    st.style.left = al(w, W, fx) + 'px'; st.style.top = al(h, H, fy) + 'px';
  });
  const p = ROOT.querySelector('.appan'); if(p && !p.dataset.init){ p.dataset.init = 1; p.scrollLeft = (p.scrollWidth - p.clientWidth) * .5; p.scrollTop = (p.scrollHeight - p.clientHeight) * .5; }
}
const hsBtn = (h, i) => { const k = h[0], fn = k === 'air' || FUNC.has(k); return `<button type="button" class="aphs ${fn ? 'fn' : ''} ${k === 'air' ? 'air' : ''}" data-a="hs" data-i="${i}" style="left:${h[2]}%;top:${h[3]}%;width:${h[4]}%;height:${h[5]}%" aria-label="${X(h[1])}">${fn ? `<i class="sp"><img src="${IC(k === 'air' ? 'ui2_land' : 'fx_spark')}" alt=""></i>` : ''}</button>`; };

