    if(tp.bought.length >= CFG.maxBuy) return toast(`1回の旅で${CFG.maxBuy}こまでだよ`);
    if(lastPt() < s.cost){ snd('ng'); return toast('ポイントが足りないよ'); }
    try{ addPoints(-s.cost, `空港お土産：${s.n}`, true); }catch(e){}
